SELECT Name, Country, Age FROM singer ORDER BY Age DESC LIMIT 100;
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer WHERE Country = 'France'
SELECT AVG(Age), MIN(Age), MAX(Age) FROM singer;
SELECT singer.Name, singer.Age AS youngest_singer_age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer)
SELECT singer.Name, singer.Age AS Age, concert.Year AS Release_Year FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age = (SELECT MAX(Age) FROM singer);
SELECT DISTINCT Country FROM singer JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age > 20;
SELECT DISTINCT Country FROM singer WHERE Age > 20;
SELECT singer.Country, COUNT(singer.Singer_ID) AS singer_count FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country
SELECT DISTINCT singer.Country, COUNT(*) AS total_singers_per_nation FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.Country;
SELECT singer.Name AS Name, singer.Age AS Age FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON singer_in_concert.Concert_ID = concert.Concert_ID WHERE singer.Age > (SELECT AVG(Age) FROM singer)
SELECT s.Song_Name, s.Age FROM singer s JOIN concert c ON s.Singer_ID = c.Singer_ID JOIN stadium st ON c.Stadium_ID = st.Stadium_ID WHERE s.Age > (SELECT AVG(Age) FROM singer)
SELECT stadium.Location, stadium.Name FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.Stadium_ID WHERE singer_in_concert.Singer_ID IN (SELECT Singer_ID FROM singer WHERE Age < 100 AND Age > 5000)
SELECT s.Name, c.Location, c.Stadium_ID FROM concert c JOIN singer_in_concert s ON c.concert_ID = s.concert_ID WHERE c.Highest BETWEEN 5000 AND 10000;
SELECT COUNT(*) FROM concert WHERE Year IN ('2014', '2015')
SELECT COUNT(*) FROM concert WHERE Year IN ('2014', '2015')
SELECT concert.Name, concert.Capacity, MAX(singer_in_concert.Song_release_year) AS Most_Consert_Year FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID WHERE Year >= '2014' GROUP BY concert.Name, concert.Capacity
SELECT s.Name, c.Capacity FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year > 2013 AND c.Year IS NOT NULL;
SELECT Name FROM stadium WHERE Concert IS NULL
SELECT Name FROM stadium WHERE Highest IS NULL OR Lowest IS NULL OR Average IS NULL
SELECT DISTINCT Country FROM singer WHERE Age > 40 OR Age < 30;
SELECT Name FROM stadium WHERE Year != 2014
SELECT s.Name FROM stadium s JOIN singer_in_concert c ON s.Stadium_ID = c.Stadium_ID JOIN concert ON c.concert_ID = concert.concert_ID WHERE concert.Year = 2014 AND s.Name NOT IN (SELECT Name FROM concert WHERE Year = 2014)
SELECT singer.Name, concert.Theme, singer_in_concert.Singer_ID AS Number_of_singers FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID;
SELECT s.Name, COUNT(c.concert_ID) AS concert_count FROM singer s JOIN singer_in_concert c ON s.Singer_ID = c.Singer_ID GROUP BY s.Name
SELECT singer.Name, COUNT(singer_in_concert.Singer_ID) AS total_concerts FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID GROUP BY singer.Name
SELECT singer.Name FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014;
SELECT singer.Name FROM singer INNER JOIN concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014;
SELECT singer.Name, singer.Country FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Theme LIKE '%Hey%'
SELECT singer.Name, singer.Country, concert.Theme FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE concert.Theme LIKE 'Hey' AND concert.Theme IS NOT NULL;
SELECT s.Name, c.Location FROM stadium s JOIN concert c ON s.Stadium_ID = c.Stadium_ID WHERE c.Year IN (2014, 2015)
