SELECT p.first_name, p.rankings.ranking_points AS rank_points FROM players p JOIN rankings r ON p.player_id = r.player_id WHERE r.rankings_points = (SELECT MAX(ranking_points) FROM rankings r2 WHERE r2.player_id = p.player_id)
