SELECT c.District, COUNT(DISTINCT c.District) AS total_cities, c.Population AS population FROM city c JOIN country l ON c.CountryCode = l.Code GROUP BY c.District, c.Population
SELECT Name, SurfaceArea FROM country ORDER BY SurfaceArea DESC LIMIT 5
SELECT CountryName, Population FROM country ORDER BY Population DESC LIMIT 3;
SELECT CountryName, Population FROM country ORDER BY Population DESC LIMIT 3;
SELECT Name FROM country JOIN city ON country.Code = city.CountryCode WHERE Population ORDER BY Population LIMIT 3
SELECT CountryCode, Name FROM country ORDER BY Population ASC LIMIT 3
SELECT COUNT(*) FROM country WHERE Continent = 'Asia'
SELECT COUNT(*) FROM country WHERE Continent = 'Asia'
SELECT country.Name, country.CountryCode FROM country JOIN city ON country.CountryCode = city.CountryCode WHERE country.Continent = 'Europe' AND city.Population >= 80000;
SELECT country.Name, country.CountryCode FROM country INNER JOIN city ON country.CountryCode = city.CountryCode WHERE country.Continent = 'Europe' AND city.Population >= 80000;
SELECT COUNT(DISTINCT country.Code) AS country_count, AVG(country.SurfaceArea) AS average_area FROM country c JOIN city d ON c.Code = d.CountryCode WHERE c.Continent = 'North America' AND c.SurfaceArea > 3000
SELECT country.Name, country.Population, country.SurfaceArea FROM country JOIN city ON country.CountryCode = city.CountryCode WHERE country.SurfaceArea > 3000 AND country.Continent = 'North America'
SELECT Name, District, CountryCode, Population FROM city WHERE Population BETWEEN 160000 AND 900000 AND Population > 160000;
SELECT Name FROM city WHERE Population BETWEEN 160000 AND 900000;
SELECT country.Name, countrylanguage.Percentage FROM countrylanguage INNER JOIN country ON countrylanguage.CountryCode = country.Code WHERE countrylanguage.IsOfficial = TRUE ORDER BY countrylanguage.Percentage DESC LIMIT 1;
SELECT country.Code, country.Name, country.Continent, country.Region, country.SurfaceArea, country.IndepYear, country.Population, country.Language, country.CountryCode, countrylanguage.Language, countrylanguage.IsOfficial, countrylanguage.Percentage FROM country INNER JOIN countrylanguage ON country.CountryCode = countrylanguage.CountryCode ORDER BY countrylanguage.Percentage DESC;
SELECT COUNT(*) AS total_countries FROM countrylanguage WHERE IsOfficial = 1 AND Percentage = (SELECT MAX(Percentage) FROM countrylanguage WHERE CountryCode = (SELECT Code FROM country WHERE Name = 'Spain') AND Language = 'Spanish')
SELECT COUNT(*) FROM countrylanguage WHERE Language = 'Spanish' AND CountryCode IN (SELECT Code FROM country WHERE Continent = 'Europe' AND Region = 'Spain')
SELECT country.Code, countrylanguage.Percentage FROM countrylanguage JOIN country ON countrylanguage.CountryCode = country.Code WHERE Language = 'Spanish' AND countrylanguage.IsOfficial = 1 ORDER BY countrylanguage.Percentage DESC LIMIT 1;
SELECT country.Code FROM countrylanguage INNER JOIN country ON countrylanguage.CountryCode = country.Code WHERE Language = 'Spanish' AND country.Language = 'Spanish'
SELECT Name, Age FROM conductor ORDER BY Age ASC;
SELECT Name, Age FROM conductor ORDER BY Age;
SELECT Name FROM conductor WHERE Nationality != '' USA;
SELECT Name FROM conductor WHERE Nationality != 'USA'
SELECT orchestra.Record_Company, orchestra.Year_of_Founded, performance.Date, performance.Weekly_rank, performance.Share FROM orchestra JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Show_ID = show.Show_ID ORDER BY orchestra.Year_of_Founded DESC;
SELECT orchestra.Orchestra, conductor.Name, orchestra.Year_of_Founded, orchestra.Record_Company FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY orchestra.Year_of_Founded ASC
SELECT COUNT(*) FROM orchestra INNER JOIN performance ON orchestra.Orchestra = performance.Orchestra_ID WHERE Performance.Type IN ('CD', 'DVD')
SELECT DISTINCT grade FROM Highschooler WHERE ID = (SELECT student_id FROM Friend WHERE student_id = (SELECT student_id FROM Likes WHERE liked_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle')))
SELECT grade FROM Highschooler WHERE ID = (SELECT student_id FROM Friend WHERE student_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle') LIMIT 1)
SELECT name FROM Highschooler WHERE grade = '10' AND ID IS NOT NULL;
SELECT name FROM Highschooler WHERE grade = '10' AND ID IS NOT NULL
SELECT ID FROM Highschooler WHERE name = 'Kyle'
SELECT ID FROM Highschooler WHERE name = 'Kyle'
SELECT COUNT(DISTINCT name) FROM Highschooler WHERE grade IN ('9', '10')
SELECT COUNT(*) FROM Highschooler WHERE grade IN ('9', '10')
SELECT DISTINCT ID, COUNT(*) AS number_of_highschoolers_per_year FROM Highschooler GROUP BY ID
