SELECT Highschooler.name FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id WHERE Friend.friend_id = Kyle.ID;
SELECT COUNT(DISTINCT Highschooler.ID) FROM Highschooler;
