SELECT COUNT(DISTINCT HIGHSHOLARER.LIKE_COUNT) FROM Highschooler INNER JOIN Likes ON Highschooler.ID = Likes.liked_id;
SELECT AVG(grade) FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT AVG(Highschooler.grade) FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT MIN(grade) FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE friend_id IS NULL)
SELECT DISTINCT grade FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE friend_id = NULL OR (SELECT COUNT(*) FROM Likes WHERE liked_id = Highschooler.ID))
SELECT o.owner_id, p.last_name, t.cell_number FROM Owners o INNER JOIN Professionals p ON o.owner_id = p.owner_id INNER JOIN Dogs d ON d.owner_id = o.owner_id INNER JOIN Treatment_Types t ON t.treatment_type_code = t.treatment_type_code INNER JOIN Dogs d ON d.professional_id = p.professional_id INNER JOIN Treatments t ON t.professional_id = p.professional_id WHERE o.state = 'Indiana' OR t.date_of_treatment > 2;
SELECT Professionals.professional_id, Professionals.last_name, Professionals.cell_number FROM Professionals JOIN Dogs ON Professionals.owner_id = Dogs.owner_id JOIN Owners ON Owners.owner_id = Professionals.owner_id WHERE Professionals.state = 'Indiana' OR Professionals.date_of_treatment > 0;
SELECT Dogs.name, Owners.first_name, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Dogs.weight > 1000 AND Dogs.owner_id = Owners.owner_id;
SELECT o.owner_id, o.first_name, o.last_name, o.street, o.city, o.state, o.zip_code, o.email_address, o.home_phone, o.cell_number, d.name, d.age, d.date_arrived, d.date_departed FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.age DESC LIMIT 1;
SELECT Dogs.owner_id, Dogs.first_name, Dogs.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT Dogs.dog_id, Professionals.first_name, Dogs.name AS first_name FROM Dogs INNER JOIN Professionals ON Dogs.owner_id = Professionals.owner_id WHERE Dogs.abandoned_yn = 'Y' AND Dogs.date_of_birth IS NOT NULL;
SELECT Dogs.id, Dogs.role, Dogs.first_name FROM Dogs JOIN Professionals ON Dogs.owner_id = Professionals.owner_id JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code JOIN Charges ON Treatments.treatment_type_code = Charges.charge_type JOIN Sizes ON Dogs.size_code = Sizes.size_code;
SELECT treatment_type_description FROM Treatment_Types WHERE treatment_type_code IN (SELECT treatment_type_code FROM Charges WHERE charge_type = 'cheapest' AND treatment_type_code IN (SELECT treatment_type_code FROM Treatments WHERE cost_of_treatment = (SELECT MIN(cost_of_treatment) FROM Treatments))
SELECT treatment_type_description FROM Treatment_Types WHERE charge_amount IS NULL;
SELECT o.owner_id, o.zip_code, d.dog_id, d.name, d.weight, d.date_of_birth, d.date_arrived, d.date_departed, t.cost_of_treatment FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types ON t.treatment_type_code = Treatment_Types.treatment_type_code GROUP BY o.owner_id, o.zip_code, d.dog_id, d.name, d.weight, d.date_of_birth, d.date_arrived, d.date_departed, t.cost_of_treatment ORDER BY t.cost_of_treatment DESC;
SELECT Dogs.id, Dogs.zip_code FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id JOIN Treatments ON Treatments.dog_id = Dogs.dog_id JOIN Professionals ON Treatments.professional_id = Professionals.professional_id GROUP BY Dogs.id ORDER BY Dogs.zip_code DESC LIMIT 1;
SELECT o.first_name, o.last_name FROM Owners o JOIN Professionals p ON o.owner_id = p.owner_id JOIN Dogs d ON d.owner_id = o.owner_id JOIN Treatments t ON d.dog_id = t.dog_id JOIN Treatment_Types t_type ON t.treatment_type_code = t_type.treatment_type_code WHERE t.cost_of_treatment < t.cost_of_treatment;
SELECT o.first_name, o.last_name, t.treatment_type_description FROM Owners o JOIN Treatments t ON o.owner_id = t.professional_id JOIN Sizes s ON t.size_code = s.size_code JOIN Breeds b ON t.breed_code = b.breed_code JOIN Dogs d ON d.owner_id = o.owner_id WHERE t.treatment_type_code IN ('small', 'medium', 'large') ORDER BY o.first_name, o.last_name
SELECT Dogs.owner_id, Dogs.name, Owners.first_name, Owners.last_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' GROUP BY Dogs.owner_id
SELECT Dogs.name, Owners.first_name FROM Dogs INNER JOIN Owners ON Dogs.owner_id = Owners.owner_id WHERE Owners.state = 'Virginia' AND Dogs.abandoned_yn = 'Y'
SELECT Dogs.owner_id, Owners.last_name FROM Dogs JOIN Owners ON Dogs.owner_id = Owners.owner_id ORDER BY Dogs.age DESC LIMIT 1;
SELECT o.last_name, d.name, d.age, d.date_of_birth, d.gender, d.date_departed, d.date_arrived, d.date_adopted, d.weight, d.abandoned_yn FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id ORDER BY d.age DESC LIMIT 1;
SELECT o.email_address FROM Owners o JOIN Dogs d ON o.owner_id = d.owner_id JOIN Sizes s ON d.size_code = s.size_code JOIN Breeds b ON d.breed_code = b.breed_code JOIN Treatment_Types t ON d.dog_id = t.dog_id JOIN Professionals p ON d.professional_id = p.professional_id WHERE o.state = 'Hawaii' OR o.state = 'Wisconsin' LIMIT 10;
SELECT email_address FROM Owners JOIN Professionals ON Owners.owner_id = Professionals.owner_id WHERE state = 'Hawaii' OR state = 'Wisconsin' AND email_address IS NOT NULL;
SELECT COUNT(DISTINCT Dogs.age) AS dogs_younger_than_average FROM Dogs;
SELECT COUNT(DISTINCT Dogs.age) FROM Dogs WHERE Dogs.age < (SELECT AVG(Dogs.age) FROM Dogs)
