SELECT MAX(cost_of_treatment) FROM Treatments;
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs WHERE Dogs.abandoned_yn = 'Y'
SELECT Dogs.name, Dogs.age, Dogs.weight, Dogs.abandoned_yn FROM Dogs;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC;
SELECT Name FROM singer ORDER BY Net_Worth_Millions ASC
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Citizenship != 'French'
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949)
SELECT Name FROM singer WHERE Birth_Year IN (1948, 1949) AND Name IS NOT NULL
SELECT Name FROM singer WHERE Net_Worth_Millions = (SELECT MAX(Net_Worth_Millions) FROM singer)
SELECT DISTINCT Citizenship, COUNT(*) AS Number_of_Singers FROM singer GROUP BY Citizenship;
SELECT DISTINCT singer.Citizenship, COUNT(song.Singer_ID) AS Total_Singers_per_Country FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY singer.Citizenship;
SELECT DISTINCT Citizenship, COUNT(*) AS Most_Common_Nationality FROM singer GROUP BY Citizenship;
SELECT DISTINCT s.Name, s.Citizenship FROM singer s JOIN song s ON s.Singer_ID = song.Singer_ID;
SELECT DISTINCT Citizenship, MAX(Song.Sales) AS Max_Net_Worth FROM singer JOIN song ON song.Singer_ID = singer.Singer_ID GROUP BY Citizenship;
SELECT MAX(Singer.Net_Worth_Millions) AS max_net_worth FROM singer;
