SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT singer.Citizenship FROM singer WHERE Birth_Year < 1945 UNION ALL SELECT singer.Citizenship FROM singer WHERE Birth_Year > 1955
SELECT Citizenship FROM singer WHERE Birth_Year < 1945 AND Citizenship = (SELECT Citizenship FROM singer WHERE Birth_Year > 1955)
SELECT property_name, property_type_code, property_address, room_count, vendor_requested_price, buyer_offered_price, agreed_selling_price, property_type_code FROM Properties JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code WHERE (property_type_code = 'house' OR property_type_code = 'apartment' AND room_count > 1);
